import numpy as np
from pocket_coffea.lib.weights import WeightWrapper

class ToyReweight(WeightWrapper):
    """Custom MC weight with ±5% symmetric variations."""

    name = "toy_reweight"
    has_variations = True

    def __call__(self, events):
        """Return nominal weight normalized to 1."""
        original = events.LHEWeight_originalXWGTUP
        return original / np.mean(original)

    def get_variation(self, events, variation_name):
        """Return weight variation (up/down)."""
        nominal = self(events)
        if variation_name == "up":
            return nominal * 1.05
        elif variation_name == "down":
            return nominal * 0.95
        return nominal

